import{_ as r,o as t,c as e,ag as l}from"./chunks/framework.DXGyWiRo.js";const f=JSON.parse('{"title":"Публичная оферта","description":"","frontmatter":{},"headers":[],"relativePath":"public-offer.md","filePath":"public-offer.md","lastUpdated":null}'),o={name:"public-offer.md"};function i(s,a,p,n,h,d){return t(),e("div",null,[...a[0]||(a[0]=[l('<h1 id="публичная-оферта" tabindex="-1">Публичная оферта <a class="header-anchor" href="#публичная-оферта" aria-label="Permalink to &quot;Публичная оферта&quot;">​</a></h1><p><strong>ИП Ульянов Алексей Владимирович</strong><br> ОГРНИП 321132600016985<br> Email: <a href="mailto:support@gosms.ru" target="_blank" rel="noreferrer">support@gosms.ru</a></p><p><em>Редакция от 21 апреля 2026 г.</em></p><hr><p>Настоящий документ является публичной офертой индивидуального предпринимателя Ульянова Алексея Владимировича (далее — <strong>Исполнитель</strong>) в соответствии со ст. 435 и 437 Гражданского кодекса Российской Федерации и адресован любому физическому или юридическому лицу (далее — <strong>Заказчик</strong>), выразившему готовность воспользоваться услугами сервиса GoSMS.</p><h2 id="_1-предмет-оферты" tabindex="-1">1. Предмет оферты <a class="header-anchor" href="#_1-предмет-оферты" aria-label="Permalink to &quot;1. Предмет оферты&quot;">​</a></h2><p>1.1. Исполнитель предоставляет Заказчику доступ к сервису <strong>GoSMS</strong> — программному комплексу для автоматизированного управления Android-устройствами в части отправки и приёма SMS-сообщений, ведения журналов, интеграции через API и сопутствующей инфраструктуры (далее — <strong>Сервис</strong>).</p><p>1.2. <strong>GoSMS не является SMS-шлюзом.</strong> Сервис предоставляет техническое решение для удалённого управления Android-устройствами Заказчика. Все SMS-сообщения отправляются непосредственно SIM-картой, установленной в устройстве Заказчика, от его имени и на его усмотрение. Исполнитель не является отправителем сообщений и не несёт ответственности за их содержание.</p><p>1.3. Состав услуг, предоставляемых в рамках тарифных планов:</p><table tabindex="0"><thead><tr><th>Услуга</th><th>Описание</th></tr></thead><tbody><tr><td>Веб-кабинет</td><td>Доступ к личному кабинету на gosms.ru</td></tr><tr><td>Android-приложение</td><td>GoSMS Client — приложение для управления устройством</td></tr><tr><td>API</td><td>RESTful-интерфейс для интеграции</td></tr><tr><td>Хранение данных</td><td>Хранение журналов сообщений и контактов</td></tr><tr><td>Техническая поддержка</td><td>Помощь по email в течение 10 рабочих дней</td></tr></tbody></table><p>1.4. Подробное описание тарифных планов и стоимость услуг размещены на сайте <a href="https://gosms.ru" target="_blank" rel="noreferrer">gosms.ru/pricing</a> и могут обновляться Исполнителем в одностороннем порядке. Изменение тарифов не затрагивает уже оплаченный период.</p><h2 id="_2-акцепт-оферты" tabindex="-1">2. Акцепт оферты <a class="header-anchor" href="#_2-акцепт-оферты" aria-label="Permalink to &quot;2. Акцепт оферты&quot;">​</a></h2><p>2.1. Акцептом оферты является совершение Заказчиком одного из следующих действий:</p><ul><li>регистрация в веб-кабинете GoSMS и нажатие кнопки «Зарегистрироваться» / «Принять условия»;</li><li>оплата любого тарифного плана;</li><li>начало фактического использования Сервиса.</li></ul><p>2.2. С момента акцепта считается заключённым <strong>договор возмездного оказания услуг</strong> (ст. 779 ГК РФ) на условиях настоящей оферты.</p><p>2.3. Акцептуя оферту, Заказчик подтверждает, что ознакомлен с настоящим документом, <a href="/user-agreement">Пользовательским соглашением</a>, <a href="/privacy-policy">Политикой конфиденциальности</a> и <a href="/aup">Правилами допустимого использования</a> и согласен с ними.</p><p>2.4. Акцепт оферты лицом, действующим от имени юридического лица или ИП, означает, что данное лицо имеет надлежащие полномочия на заключение договора.</p><h2 id="_3-права-и-обязанности-сторон" tabindex="-1">3. Права и обязанности сторон <a class="header-anchor" href="#_3-права-и-обязанности-сторон" aria-label="Permalink to &quot;3. Права и обязанности сторон&quot;">​</a></h2><h3 id="_3-1-обязанности-исполнителя" tabindex="-1">3.1. Обязанности Исполнителя <a class="header-anchor" href="#_3-1-обязанности-исполнителя" aria-label="Permalink to &quot;3.1. Обязанности Исполнителя&quot;">​</a></h3><ul><li>Обеспечивать работоспособность Сервиса в соответствии с выбранным тарифным планом.</li><li>Уведомлять Заказчика о плановых технических работах не менее чем за 24 часа через личный кабинет или email.</li><li>Хранить и обрабатывать персональные данные Заказчика в соответствии с <a href="/privacy-policy">Политикой конфиденциальности</a> и требованиями ФЗ-152.</li><li>Рассматривать обращения Заказчика в течение 10 рабочих дней.</li></ul><h3 id="_3-2-права-исполнителя" tabindex="-1">3.2. Права Исполнителя <a class="header-anchor" href="#_3-2-права-исполнителя" aria-label="Permalink to &quot;3.2. Права Исполнителя&quot;">​</a></h3><ul><li>Приостанавливать доступ к Сервису при нарушении Заказчиком условий настоящей оферты или <a href="/aup">Правил допустимого использования</a>.</li><li>Изменять стоимость услуг в одностороннем порядке с уведомлением Заказчика не менее чем за 15 календарных дней до вступления изменений в силу.</li><li>Привлекать третьих лиц для исполнения обязательств по договору.</li></ul><h3 id="_3-3-обязанности-заказчика" tabindex="-1">3.3. Обязанности Заказчика <a class="header-anchor" href="#_3-3-обязанности-заказчика" aria-label="Permalink to &quot;3.3. Обязанности Заказчика&quot;">​</a></h3><ul><li>Своевременно оплачивать услуги согласно выбранному тарифному плану.</li><li>Использовать Сервис только в соответствии с его назначением и действующим законодательством РФ.</li><li>Самостоятельно обеспечивать соблюдение ФЗ-38 «О рекламе» и иных применимых норм при формировании и отправке сообщений.</li><li>Не передавать реквизиты доступа к учётной записи третьим лицам.</li><li>Незамедлительно уведомлять Исполнителя о несанкционированном доступе к учётной записи.</li></ul><h3 id="_3-4-права-заказчика" tabindex="-1">3.4. Права Заказчика <a class="header-anchor" href="#_3-4-права-заказчика" aria-label="Permalink to &quot;3.4. Права Заказчика&quot;">​</a></h3><ul><li>Использовать Сервис в соответствии с выбранным тарифом.</li><li>Получать техническую поддержку по адресу <a href="mailto:support@gosms.ru" target="_blank" rel="noreferrer">support@gosms.ru</a>.</li><li>Отказаться от услуг в любое время в порядке, предусмотренном разд. 7 настоящей оферты.</li></ul><h2 id="_4-стоимость-и-порядок-оплаты" tabindex="-1">4. Стоимость и порядок оплаты <a class="header-anchor" href="#_4-стоимость-и-порядок-оплаты" aria-label="Permalink to &quot;4. Стоимость и порядок оплаты&quot;">​</a></h2><p>4.1. Услуги оказываются на условиях предоплаты. Доступ к Сервису предоставляется после зачисления денежных средств на счёт Исполнителя.</p><p>4.2. Оплата производится в рублях Российской Федерации через платёжные системы, указанные в личном кабинете.</p><p>4.3. Датой оплаты считается дата зачисления денежных средств на расчётный счёт Исполнителя или счёт платёжного агента.</p><p>4.4. Исполнитель вправе установить минимальную сумму пополнения баланса.</p><h2 id="_5-возврат-денежных-средств" tabindex="-1">5. Возврат денежных средств <a class="header-anchor" href="#_5-возврат-денежных-средств" aria-label="Permalink to &quot;5. Возврат денежных средств&quot;">​</a></h2><p>5.1. Заказчик вправе отказаться от услуг и потребовать возврата неиспользованного остатка денежных средств в любое время в соответствии со ст. 32 Закона РФ «О защите прав потребителей» и ст. 782 ГК РФ.</p><p>5.2. Для возврата необходимо направить заявление на адрес <a href="mailto:support@gosms.ru" target="_blank" rel="noreferrer">support@gosms.ru</a> с указанием реквизитов для перечисления средств.</p><p>5.3. Возврат производится в течение <strong>10 рабочих дней</strong> с даты получения заявления за вычетом фактически оказанных услуг и расходов платёжных систем (если применимо).</p><p>5.4. Возврату не подлежат средства, использованные до подачи заявления о расторжении договора.</p><h2 id="_6-ответственность-сторон" tabindex="-1">6. Ответственность сторон <a class="header-anchor" href="#_6-ответственность-сторон" aria-label="Permalink to &quot;6. Ответственность сторон&quot;">​</a></h2><p>6.1. Сервис предоставляется «как есть» (as is). Исполнитель не гарантирует непрерывную работу Сервиса и не несёт ответственности за убытки, вызванные техническими неисправностями, действиями третьих лиц или обстоятельствами непреодолимой силы.</p><p>6.2. Исполнитель не несёт ответственности за содержание SMS-сообщений, отправленных Заказчиком, и за нарушение Заказчиком требований ФЗ-38, ФЗ-149 и иного применимого законодательства.</p><p>6.3. Заказчик несёт полную ответственность за законность своих действий при использовании Сервиса, в том числе за наличие согласия получателей сообщений.</p><p>6.4. Ответственность Исполнителя по договору ограничена стоимостью услуг, оплаченных Заказчиком за последние 3 (три) месяца.</p><h2 id="_7-срок-деиствия-договора-и-его-расторжение" tabindex="-1">7. Срок действия договора и его расторжение <a class="header-anchor" href="#_7-срок-деиствия-договора-и-его-расторжение" aria-label="Permalink to &quot;7. Срок действия договора и его расторжение&quot;">​</a></h2><p>7.1. Договор вступает в силу с момента акцепта оферты и действует бессрочно.</p><p>7.2. Каждая из сторон вправе расторгнуть договор в одностороннем порядке, уведомив другую сторону за <strong>15 календарных дней</strong>.</p><p>7.3. Исполнитель вправе расторгнуть договор немедленно (без предварительного уведомления) при нарушении Заказчиком <a href="/aup">Правил допустимого использования</a> или иных существенных условий договора.</p><p>7.4. При расторжении договора Заказчику возвращается остаток средств в соответствии с разд. 5.</p><h2 id="_8-изменение-оферты" tabindex="-1">8. Изменение оферты <a class="header-anchor" href="#_8-изменение-оферты" aria-label="Permalink to &quot;8. Изменение оферты&quot;">​</a></h2><p>8.1. Исполнитель вправе изменять условия оферты. Новая редакция размещается по адресу <a href="https://legal.gosms.ru/public-offer" target="_blank" rel="noreferrer">legal.gosms.ru/public-offer</a> и вступает в силу через <strong>15 календарных дней</strong> с момента публикации.</p><p>8.2. Продолжение использования Сервиса после вступления в силу новой редакции оферты означает согласие Заказчика с изменёнными условиями.</p><p>8.3. Если Заказчик не согласен с изменениями, он вправе расторгнуть договор в порядке, предусмотренном разд. 7.</p><h2 id="_9-разрешение-споров" tabindex="-1">9. Разрешение споров <a class="header-anchor" href="#_9-разрешение-споров" aria-label="Permalink to &quot;9. Разрешение споров&quot;">​</a></h2><p>9.1. Споры разрешаются путём переговоров. Обязательный досудебный (претензионный) порядок — 30 (тридцать) календарных дней с момента направления претензии.</p><p>9.2. Претензии направляются на адрес <a href="mailto:support@gosms.ru" target="_blank" rel="noreferrer">support@gosms.ru</a> или заказным письмом по месту регистрации Исполнителя.</p><p>9.3. При недостижении соглашения спор передаётся в суд по месту нахождения Исполнителя в соответствии с законодательством Российской Федерации. По спорам с потребителями применяются правила подсудности, установленные ЗоЗПП.</p><p>9.4. Договор регулируется законодательством Российской Федерации.</p><h2 id="_10-реквизиты-исполнителя" tabindex="-1">10. Реквизиты Исполнителя <a class="header-anchor" href="#_10-реквизиты-исполнителя" aria-label="Permalink to &quot;10. Реквизиты Исполнителя&quot;">​</a></h2><p><strong>ИП Ульянов Алексей Владимирович</strong><br> ОГРНИП 321132600016985<br> Email: <a href="mailto:support@gosms.ru" target="_blank" rel="noreferrer">support@gosms.ru</a><br> Сайт: <a href="https://gosms.ru" target="_blank" rel="noreferrer">https://gosms.ru</a></p>',57)])])}const _=r(o,[["render",i]]);export{f as __pageData,_ as default};
